content.content:
1	// API contract between the DealScope FastAPI server (src/dealscope/api) and this frontend.
2	// All user-facing wording is produced server-side in plain language; the UI must not show raw
3	// internal codes (reason codes, stage enums) except inside an optional "technical details" disclosure.
4	
5	export type RunMode = "live" | "synthetic";
6	export type Tone = "good" | "neutral" | "caution" | "bad" | "info";
7	
8	export interface ProviderStatus {
9	  key: "crustdata" | "llm" | "neatlogs" | "jobs_pricing";
10	  label: string; // e.g. "Company data (Crustdata)"
11	  connected: boolean;
12	  detail: string; // e.g. "Connected" / "Model: gemini-3.1-flash-lite" / "Not configured"
13	}
14	
15	export interface BudgetSummary {
16	  spendable: number; // credits allowed for product use (total minus reserve)
17	  estimated_used: number;
18	  actual_used: number; // confirmed from provider response headers
19	  reserved: number;
20	  remaining: number;
21	  unknown_calls: number;
22	  reserve: number; // credits held back and never spent
23	  total: number;
24	}
25	
26	export interface StatusResponse {
27	  providers: ProviderStatus[];
28	  live_budget: BudgetSummary;
29	  max_case_credits: number;
30	  live_available: boolean; // false when no Crustdata key: live runs are refused, never faked
31	}
32	
33	export interface Scenario {
34	  id: string; // "scenario_a" | "scenario_b" | "synthetic_case"
35	  label: string;
36	  description: string;
37	  target_domain: string;
38	  competitor_domains: string[];
39	  deal_thesis: string;
40	}
41	
42	export interface FaultOption {
43	  id: string; // "none" | "retry_success" | "retry_exhausted" | "auth_failure"
44	  label: string;
45	  description: string;
46	}
47	
48	export interface IdentityCandidate {
49	  name: string | null;
50	  primary_domain: string | null;
51	  employee_count_range: string | null;
52	}
53	
54	export interface IdentityResult {
55	  domain: string;
56	  ok: boolean;
57	  status: "ok" | "ambiguous" | "mismatch" | "no_match" | "error";
58	  resolved_name: string | null;
59	  match_count: number;
60	  message: string; // plain-language explanation, e.g. "23 different companies use this domain..."
61	  candidates: IdentityCandidate[];
62	}
63	
64	export interface CreateCaseRequest {
65	  target_domain: string;
66	  competitor_domains: string[];
67	  deal_thesis: string;
68	  lookback_months: number;
69	  max_case_credits: number;
70	  mode: RunMode;
71	  scenario_id?: string; // synthetic only
72	  fault_id?: string; // synthetic only
73	}
74	
75	export interface CreateCaseResponse {
76	  case_id: string;
77	}
78	
79	export interface CaseListItem {
80	  case_id: string;
81	  target: string;
82	  mode: RunMode;
83	  status_label: string; // "Complete", "Partial - can resume", "Running", "Failed"
84	  tone: Tone;
85	  risk_label: string; // "Watch (32/100)" or "Not enough evidence"
86	  updated_at: string; // ISO
87	}
88	
89	export interface Assessment {
90	  risk_score: number | null; // 0-100, null when coverage < 60%
91	  risk_band: string | null; // "Low signal" | "Watch" | "Elevated" | "High signal"
92	  risk_tone: Tone;
93	  headline: string; // one plain sentence summarising the result
94	  coverage_pct: number;
95	  coverage_label: string; // "Enough evidence to score" / "Provisional" / "Not enough evidence"
96	  confidence: number; // 0-100, evidence quality (separate from risk)
97	  confidence_label: string; // "High" | "Medium" | "Low"
98	  explainer: string; // how to read risk vs coverage vs confidence
99	}
100	
101	export interface SignalView {
102	  id: string; // "S1".."S5"
103	  name: string; // plain name, e.g. "Engineering team vs. company growth"
104	  question: string; // the question this signal answers
105	  weight_pct: number;
106	  scored: boolean;
107	  score: number | null;
108	  band: string | null; // band label for this signal score
109	  tone: Tone;
110	  status_label: string; // "Scored" | "Partly scored (thin data)" | "Not scored"
111	  confidence: number;
112	  finding: string; // plain-language result, built from reason codes and raw measures
113	  why_it_matters: string;
114	  limitations: string[];
115	  evidence_ids: string[];
116	  technical: { reason_codes: string[]; state: string };
117	}
118	
119	export interface EvidenceRef {
120	  id: string;
121	  label: string; // "Company profile - notion.com" / "Job posting - Staff SRE"
122	  date: string | null;
123	  source: string; // "Crustdata /job/search" or "Synthetic fixture"
124	}
125	
126	export interface FindingView {
127	  id: string;
128	  kind: "Fact" | "Interpretation" | "Hypothesis" | "Question";
129	  severity: "low" | "medium" | "high";
130	  text: string;
131	  verification: "Verified" | "Verified with caveats";
132	  caveats: string[];
133	  evidence: EvidenceRef[];
134	  counter_evidence: EvidenceRef[];
135	  alternatives: string[];
136	  limitations: string[];
137	}
138	
139	export interface StepView {
140	  n: number;
141	  at: string; // ISO timestamp
142	  kind: "plan" | "tool" | "retry" | "score" | "stage" | "resume" | "blocked" | "note";
143	  title: string; // plain, e.g. "Checked open engineering roles at notion.com"
144	  detail: string; // plain explanation, e.g. "Found 25 postings; 14 were reposted."
145	  actor: string; // "AI planner" | "Rule-based planner" | "Baseline" | "System" | "Retry policy"
146	  tone: Tone;
147	  credits: string | null; // e.g. "2 credits (confirmed)" / "from cache, 0 credits"
148	}
149	
150	export interface CompanyRow {
151	  domain: string;
152	  role: "Target" | "Peer";
153	  name: string | null;
154	  headcount: number | null;
155	  total_growth: Record<string, number>; // period label ("3m","6m","12m") -> percent
156	  engineering_headcount: number | null;
157	  engineering_growth: Record<string, number>;
158	  open_jobs: number | null;
159	  data_quality_flags: string[]; // plain sentences
160	  evidence_id: string;
161	}
162	
163	export interface PersonRow {
164	  ref: string; // opaque, never a name
165	  role_group: string; // plain: "Technical leadership"
166	  title_at_target: string | null;
167	  left_target: string | null; // "2026-05" or null if still there / unknown
168	  status: string; // "Left in lookback window" | "Left earlier" | "Still at target" | "End date unknown"
169	  now_at: string | null;
170	  now_at_competitor: boolean;
171	  evidence_id: string;
172	}
173	
174	export interface JobRow {
175	  title: string;
176	  capability: string; // plain: "Security"
177	  posted: string | null;
178	  reposted: boolean | null;
179	  openings: number | null;
180	  url: string | null;
181	  evidence_id: string;
182	}
183	
184	export interface CreditsView {
185	  cap: number;
186	  estimated_used: number;
187	  actual_used: number;
188	  reserved: number;
189	  remaining: number;
190	  unknown_calls: number;
191	  simulated: boolean; // synthetic runs: simulated accounting, no real credits
192	}
193	
194	export interface VerificationView {
195	  published: number;
196	  verified: number;
197	  with_caveats: number;
198	  rejected: number;
199	  grounded_rate: number | null; // 0-1
200	  rejected_reasons: { reason: string; count: number }[]; // plain reasons
201	  ai_draft_used: boolean; // false when the AI write-up was unavailable and only rule-based findings are shown
202	}
203	
204	export interface CaseView {
205	  case_id: string;
206	  mode: RunMode;
207	  synthetic: boolean;
208	  target: string;
209	  peers: string[];
210	  thesis: string;
211	  lookback_months: number;
212	  running: boolean;
213	  status_label: string;
214	  status_tone: Tone;
215	  status_detail: string; // plain explanation of how/why the run ended
216	  can_resume: boolean;
217	  current_question: string | null;
218	  planner_turns: number;
219	  tool_calls: number;
220	  assessment: Assessment | null; // null until the first scoring
221	  signals: SignalView[];
222	  findings: FindingView[];
223	  questions: string[]; // diligence questions for management
224	  steps: StepView[];
225	  companies: CompanyRow[];
226	  people: PersonRow[];
227	  jobs: JobRow[];
228	  credits: CreditsView;
229	  verification: VerificationView | null;
230	  trace_ids: string[];
231	  llm_model: string | null;
232	  updated_at: string;
233	  report_available: boolean;
234	}
235

1	// Shape of the "How it works" walkthrough content (frontend/src/content/howItWorks.ts).
2	// Evidence images are repository paths under evidence/ (e.g. "evidence/neatlogs/screenshots/x.png");
3	// the frontend loads them from the API at /api/evidence/<path relative to evidence/>.
4	
5	export interface ContentTable {
6	  headers: string[];
7	  rows: string[][];
8	}
9	
10	export interface EvidenceImage {
11	  path: string; // repo-relative, must start with "evidence/"
12	  caption: string;
13	}
14	
15	export interface HowItWorksSection {
16	  id: string; // anchor id, kebab-case
17	  title: string;
18	  summary: string; // one or two sentences shown in the section header
19	  paragraphs: string[];
20	  bullets?: string[];
21	  table?: ContentTable;
22	  images?: EvidenceImage[];
23	}
24	
25	export interface HowItWorksContent {
26	  intro: string;
27	  sections: HowItWorksSection[];
28	}
