import type {
  CaseListItem,
  CaseView,
  CreateCaseRequest,
  CreateCaseResponse,
  FaultOption,
  IdentityResult,
  Scenario,
  StatusResponse,
} from "./types";
import * as mocks from "../mocks/mockApi";

export class ApiError extends Error {
