  --navy: #14233f;
  --navy-ink: #ffffff;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --accent-soft: #e2f3f1;
  --focus: #1d4ed8;
  --shadow: 0 1px 2px rgba(15, 27, 51, 0.06), 0 2px 8px rgba(15, 27, 51, 0.05);

  --good-fg: #14633a;
  --good-bg: #e3f4ea;
  --good-bar: #2f9e66;
  --neutral-fg: #3d4a63;
  --neutral-bg: #e9edf3;
  --neutral-bar: #7b88a1;
  --caution-fg: #7a4a00;
  --caution-bg: #fdefd2;
  --caution-bar: #d9962b;
  --bad-fg: #9b1c1c;
  --bad-bg: #fde6e6;
  --bad-bar: #d04545;
  --info-fg: #1c4a99;
  --info-bg: #e4edfb;
  --info-bar: #4a7bd0;

  --radius: 10px;
  --radius-sm: 6px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0c1424;
    --surface: #131d33;
    --surface-2: #17233c;
    --ink: #e8edf6;
    --ink-2: #c0cadb;
    --muted: #9aa8c0;
    --line: #25334f;
    --line-strong: #34456a;
    --navy: #0a1120;
    --accent: #36b7ac;
    --accent-ink: #04201d;
    --accent-soft: #123a3a;
    --focus: #8fb4ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);

    --good-fg: #8fe0b2;
    --good-bg: #123a27;
    --good-bar: #3fb77a;
    --neutral-fg: #c0cadb;
    --neutral-bg: #1f2c47;
    --neutral-bar: #7b88a1;
    --caution-fg: #f4c677;
    --caution-bg: #3b2c0e;
    --caution-bar: #e0a23a;
    --bad-fg: #ffa5a5;
    --bad-bg: #431818;
    --bad-bar: #e06a6a;
    --info-fg: #a9c6ff;
    --info-bg: #172c52;
    --info-bar: #5f8fe0;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 76px; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { line-height: 1.25; margin: 0 0 0.5em; color: var(--ink); }
h1 { font-size: 1.6rem; letter-spacing: -0.01em; }
h2 { font-size: 1.25rem; }
h3 { font-size: 1.05rem; }
h4 { font-size: 0.95rem; }
p { margin: 0 0 0.8em; }
a { color: var(--accent); }
a:hover { text-decoration-thickness: 2px; }
code, .mono { font-family: var(--mono); font-size: 0.88em; }
ul, ol { margin: 0 0 0.8em; padding-left: 1.3em; }
li { margin-bottom: 0.25em; }
table { border-collapse: collapse; width: 100%; }

:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 3px; }

.skip-link {
  position: absolute; left: -999px; top: 0; background: var(--accent); color: var(--accent-ink);
  padding: 8px 14px; z-index: 100;
}
.skip-link:focus { left: 8px; top: 8px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* Layout */
.topbar { background: var(--navy); color: var(--navy-ink); position: sticky; top: 0; z-index: 30; }
.topbar-inner {
  max-width: 1160px; margin: 0 auto; padding: 10px 16px; display: flex; align-items: center;
  gap: 8px 24px; flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: inherit; }
.brand-mark { flex: none; }
.brand-name { font-weight: 700; font-size: 1.15rem; letter-spacing: 0.01em; display: block; line-height: 1.1; }
.brand-tag { font-size: 0.75rem; opacity: 0.8; display: block; }
.nav { display: flex; gap: 4px; flex-wrap: wrap; flex: 1; }
.nav a {
  color: #d6deee; text-decoration: none; padding: 7px 12px; border-radius: var(--radius-sm); font-weight: 500;
  font-size: 0.93rem;
}
.nav a:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.nav a.active { background: rgba(255, 255, 255, 0.16); color: #fff; }
.topbar :focus-visible { outline-color: #9ec1ff; }

.systems { position: relative; }
.systems-btn {
  display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.1); color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 999px; padding: 6px 12px; font: inherit;
  font-size: 0.85rem; cursor: pointer;
}
.systems-btn:hover { background: rgba(255, 255, 255, 0.18); }
.systems-panel {
  position: absolute; right: 0; top: calc(100% + 8px); width: min(360px, calc(100vw - 32px));
  background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25); padding: 14px; z-index: 40;
}
.systems-panel h2 { font-size: 0.95rem; margin-bottom: 8px; }
.system-row { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-top: 1px solid var(--line); }
.system-row:first-of-type { border-top: 0; }
.system-label { font-weight: 600; font-size: 0.9rem; }
.system-detail { font-size: 0.82rem; color: var(--muted); }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; flex: none; margin-top: 6px; }
.dot.on { background: #3fcf8e; }
.dot.off { background: transparent; border: 2px solid #f0a0a0; }
.systems-btn .dot { margin-top: 0; }
.dots { display: inline-flex; gap: 4px; }

.main { max-width: 1160px; margin: 0 auto; padding: 24px 16px 64px; }
.page-head { margin-bottom: 20px; }
.page-head p { color: var(--muted); max-width: 70ch; margin-bottom: 0; }
.footer { text-align: center; color: var(--muted); font-size: 0.82rem; padding: 0 16px 32px; }

/* Cards, buttons */
.card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px; box-shadow: var(--shadow);
}
.card + .card, .stack > * + * { margin-top: 16px; }
.card h2 { margin-bottom: 0.4em; }
.section { margin-top: 28px; }
.section-head { margin-bottom: 12px; }
.section-head h2 { margin-bottom: 2px; }
.section-head p { color: var(--muted); margin: 0; font-size: 0.92rem; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 9px 16px;
  border-radius: var(--radius-sm); border: 1px solid var(--line-strong); background: var(--surface);
  color: var(--ink); font: inherit; font-weight: 600; font-size: 0.92rem; cursor: pointer; text-decoration: none;
  min-height: 40px;
}
.btn:hover:not(:disabled) { background: var(--surface-2); border-color: var(--muted); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn.primary:hover:not(:disabled) { filter: brightness(0.93); background: var(--accent); }
.btn.small { padding: 5px 10px; min-height: 32px; font-size: 0.84rem; }
.btn-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.link-btn {
  background: none; border: 0; padding: 0; color: var(--accent); font: inherit; cursor: pointer;
  text-decoration: underline;
}

/* Pills, badges */
.pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.8rem;
  font-weight: 600; white-space: nowrap; background: var(--tone-bg); color: var(--tone-fg);
  border: 1px solid transparent;
}
.pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--tone-bar); }
.pill.plain::before { display: none; }
.badge {
  display: inline-block; padding: 2px 9px; border-radius: var(--radius-sm); font-size: 0.78rem; font-weight: 700;
  background: var(--tone-bg); color: var(--tone-fg); letter-spacing: 0.02em;
}
.tone-good { --tone-fg: var(--good-fg); --tone-bg: var(--good-bg); --tone-bar: var(--good-bar); }
.tone-neutral { --tone-fg: var(--neutral-fg); --tone-bg: var(--neutral-bg); --tone-bar: var(--neutral-bar); }
.tone-caution { --tone-fg: var(--caution-fg); --tone-bg: var(--caution-bg); --tone-bar: var(--caution-bar); }
.tone-bad { --tone-fg: var(--bad-fg); --tone-bg: var(--bad-bg); --tone-bar: var(--bad-bar); }
.tone-info { --tone-fg: var(--info-fg); --tone-bg: var(--info-bg); --tone-bar: var(--info-bar); }

.mode-synthetic { background: var(--caution-bg); color: var(--caution-fg); border: 1px solid var(--caution-bar); }
.mode-live { background: var(--info-bg); color: var(--info-fg); border: 1px solid var(--info-bar); }

.banner {
  display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius);
  background: var(--tone-bg); color: var(--tone-fg); border: 1px solid var(--tone-bar); margin-bottom: 14px;
}
.banner svg { flex: none; margin-top: 2px; }
.banner strong { display: block; }
.banner p { margin: 0; }
.banner-demo { font-weight: 700; font-size: 1rem; }

/* Forms */
.field { margin-bottom: 18px; }
.field label, .field .label, legend.label { display: block; font-weight: 600; margin-bottom: 4px; font-size: 0.93rem; }
.help { color: var(--muted); font-size: 0.84rem; margin: 4px 0 0; }
.input, .textarea, .select {
  width: 100%; font: inherit; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm); padding: 9px 11px; min-height: 40px;
}
.textarea { min-height: 96px; resize: vertical; }
.input[aria-invalid="true"], .textarea[aria-invalid="true"], .select[aria-invalid="true"] { border-color: var(--bad-bar); }
.input:disabled { background: var(--surface-2); }
.error-text { color: var(--bad-fg); font-size: 0.86rem; margin: 4px 0 0; font-weight: 500; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
.check { display: flex; gap: 10px; align-items: flex-start; }
.check input { width: 20px; height: 20px; margin-top: 2px; flex: none; accent-color: var(--accent); }

.choice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; }
.choice {
  display: block; position: relative; border: 2px solid var(--line); border-radius: var(--radius); padding: 14px 16px;
  background: var(--surface); cursor: pointer;
}
.choice:hover { border-color: var(--line-strong); }
.choice.selected { border-color: var(--accent); background: var(--accent-soft); }
.choice.disabled { opacity: 0.65; cursor: not-allowed; background: var(--surface-2); }
.choice input { position: absolute; opacity: 0; inset: 0; width: 100%; height: 100%; cursor: inherit; margin: 0; }
.choice:has(input:focus-visible) { outline: 3px solid var(--focus); outline-offset: 2px; }
.choice-title { font-weight: 700; display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.choice-body { color: var(--ink-2); font-size: 0.9rem; margin: 6px 0 0; }
.choice-check { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--line-strong); flex: none; }
.choice.selected .choice-check { border-color: var(--accent); background: var(--accent); box-shadow: inset 0 0 0 3px var(--accent-soft); }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.chip {
  display: inline-flex; align-items: center; gap: 4px; background: var(--neutral-bg); color: var(--ink);
  border-radius: 999px; padding: 3px 4px 3px 11px; font-size: 0.86rem;
}
.chip button {
  border: 0; background: transparent; cursor: pointer; width: 22px; height: 22px; border-radius: 50%; color: inherit;
  display: inline-flex; align-items: center; justify-content: center;
}
.chip button:hover { background: rgba(0, 0, 0, 0.12); }

/* Tables */
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.table-wrap table { min-width: 560px; }
th, td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: top; font-size: 0.9rem; }
th { background: var(--surface-2); font-weight: 600; color: var(--ink-2); font-size: 0.82rem; white-space: nowrap; }
tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
.pos { color: var(--good-fg); }
.neg { color: var(--bad-fg); }
.flag-list { list-style: none; padding: 0; margin: 4px 0 0; }
.flag-list li { color: var(--caution-fg); background: var(--caution-bg); border-radius: 4px; padding: 2px 8px; font-size: 0.8rem; margin-bottom: 3px; }

.table-stack { display: none; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 2px solid var(--line); margin-bottom: 14px; flex-wrap: wrap; }
.tab {
  background: none; border: 0; border-bottom: 3px solid transparent; margin-bottom: -2px; padding: 9px 14px;
  font: inherit; font-weight: 600; color: var(--muted); cursor: pointer;
}
.tab:hover { color: var(--ink); }
.tab[aria-selected="true"] { color: var(--accent); border-bottom-color: var(--accent); }
.tab .count { font-weight: 500; opacity: 0.8; margin-left: 4px; }

/* Disclosure */
details.disclosure { border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); margin-top: 10px; }
details.disclosure > summary {
  cursor: pointer; padding: 8px 12px; font-weight: 600; font-size: 0.88rem; color: var(--ink-2); list-style: none;
  display: flex; align-items: center; gap: 8px;
}
details.disclosure > summary::-webkit-details-marker { display: none; }
details.disclosure > summary::before {
  content: ""; width: 7px; height: 7px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
  transform: rotate(-45deg); transition: transform 0.15s; flex: none;
}
details.disclosure[open] > summary::before { transform: rotate(45deg); }
details.disclosure > .disc-body { padding: 4px 14px 12px; }

/* Case header */
.case-head h1 { margin-bottom: 4px; word-break: break-word; }
.case-meta { display: flex; gap: 8px 12px; flex-wrap: wrap; align-items: center; margin: 8px 0; }
.peer-list { color: var(--ink-2); margin: 4px 0; }
.thesis { background: var(--surface-2); border-left: 3px solid var(--accent); padding: 10px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; white-space: pre-wrap; margin: 0; }

/* Summary */
.summary { display: grid; grid-template-columns: minmax(200px, 260px) 1fr; gap: 28px; align-items: start; }
.score-box { text-align: center; padding: 18px 12px; border-radius: var(--radius); background: var(--tone-bg); color: var(--tone-fg); }
.score-num { font-size: 4rem; font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.score-num small { font-size: 1.1rem; font-weight: 600; opacity: 0.75; }
.score-none { font-size: 1.3rem; font-weight: 700; line-height: 1.25; padding: 10px 0; }
.score-band { font-size: 1.15rem; font-weight: 700; margin-top: 6px; }
.score-cap { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; margin-bottom: 6px; opacity: 0.85; }
.headline { font-size: 1.2rem; font-weight: 600; line-height: 1.4; margin-bottom: 16px; }
.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.meter-head { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; margin-bottom: 4px; }
.meter-name { font-weight: 700; font-size: 0.9rem; }
.meter-val { font-weight: 700; font-variant-numeric: tabular-nums; }
.meter-track { height: 12px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; position: relative; }
.meter-fill { height: 100%; border-radius: 999px; background: var(--tone-bar); }
.meter-sub { font-size: 0.84rem; color: var(--muted); margin-top: 3px; }
.meter-ticks { position: absolute; inset: 0; pointer-events: none; }
.meter-ticks span { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--surface); opacity: 0.8; }
.infobox { background: var(--info-bg); color: var(--ink); border: 1px solid var(--info-bar); border-radius: var(--radius-sm); padding: 10px 14px; margin-top: 16px; font-size: 0.9rem; }
.infobox strong { color: var(--info-fg); display: block; margin-bottom: 2px; }
.infobox p { margin: 0; }

/* Signals */
.signals { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; }
.signal { display: flex; flex-direction: column; margin: 0 !important; }
.signal-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
.signal-name { font-size: 1.02rem; margin: 0; }
.signal-q { color: var(--muted); font-size: 0.88rem; margin: 2px 0 10px; font-style: italic; }
.bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
.bar-track { flex: 1; height: 10px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; }
.bar-fill { height: 100%; background: var(--tone-bar); border-radius: 999px; }
.bar-val { font-weight: 700; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; font-size: 0.9rem; }
.kv { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 0.84rem; margin-bottom: 8px; }
.signal .finding { margin-bottom: 8px; }
.signal h4 { margin: 10px 0 2px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.signal ul.lim { color: var(--ink-2); font-size: 0.88rem; margin: 2px 0 0; }
.tech-list { font-family: var(--mono); font-size: 0.8rem; word-break: break-word; }

/* Findings */
.finding-group + .finding-group { margin-top: 20px; }
.finding-group > h3 { display: flex; gap: 8px; align-items: baseline; }
.finding-group > h3 .muted { font-weight: 400; font-size: 0.85rem; }
.finding { margin-top: 10px !important; border-left: 4px solid var(--tone-bar); padding: 14px 16px; }
.finding-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 6px; }
.finding-text { font-weight: 600; margin: 0 0 8px; font-size: 1rem; }
.finding h4 { margin: 10px 0 2px; font-size: 0.85rem; color: var(--ink-2); }
.finding ul { margin: 2px 0 0; font-size: 0.9rem; color: var(--ink-2); }
.ev-list { list-style: none; padding: 0; }
.ev-item { padding: 6px 10px; background: var(--surface-2); border-radius: var(--radius-sm); margin-bottom: 4px; border-left: 3px solid var(--good-bar); }
.ev-item.counter { border-left-color: var(--bad-bar); background: var(--bad-bg); }
.ev-label { font-weight: 600; font-size: 0.88rem; }
.ev-meta { color: var(--muted); font-size: 0.8rem; }

/* Questions */
.question-list { padding-left: 0; list-style: none; counter-reset: q; }
.question-list li { counter-increment: q; display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); margin: 0; }
.question-list li:last-child { border-bottom: 0; }
.question-list li::before {
  content: counter(q); flex: none; width: 26px; height: 26px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
  font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-size: 0.85rem;
}

/* Timeline */
.timeline { list-style: none; padding: 0; margin: 0; position: relative; }
.timeline li { position: relative; padding: 0 0 18px 30px; margin: 0; }
.timeline li::before { content: ""; position: absolute; left: 9px; top: 18px; bottom: -2px; width: 2px; background: var(--line); }
.timeline li:last-child::before { display: none; }
.tl-dot { position: absolute; left: 2px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--tone-bar); border: 3px solid var(--surface); box-shadow: 0 0 0 1px var(--tone-bar); }
.tl-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.tl-title { font-weight: 600; }
.tl-detail { color: var(--ink-2); margin: 2px 0 0; font-size: 0.9rem; }
.tl-meta { color: var(--muted); font-size: 0.8rem; display: flex; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
.actor { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 1px 8px; border-radius: 4px; background: var(--tone-bg); color: var(--tone-fg); }

/* Progress */
.progress-panel { border-left: 5px solid var(--accent); }
.progress-q { font-size: 1.05rem; font-weight: 600; margin: 6px 0 12px; }
.spinner {
  width: 18px; height: 18px; border-radius: 50%; border: 3px solid var(--line-strong); border-top-color: var(--accent);
  animation: spin 0.9s linear infinite; display: inline-block; flex: none;
}
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 3s; } html { scroll-behavior: auto; } }
.progress-head { display: flex; align-items: center; gap: 10px; font-weight: 700; }
.live-steps { max-height: 320px; overflow: auto; margin-top: 8px; }

/* Cost */
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
.stat { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 12px; }
.stat-v { font-size: 1.4rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
.stat-k { color: var(--muted); font-size: 0.82rem; }
.cols-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.cols-2 > .card { margin: 0 !important; }
.trace-row { display: flex; gap: 8px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
.trace-id { font-family: var(--mono); font-size: 0.82rem; background: var(--surface-2); border: 1px solid var(--line); padding: 3px 8px; border-radius: 4px; word-break: break-all; }

/* States */
.state { text-align: center; padding: 36px 16px; color: var(--muted); }
.state .spinner { margin-bottom: 8px; }
.error-box { background: var(--bad-bg); color: var(--bad-fg); border: 1px solid var(--bad-bar); border-radius: var(--radius); padding: 12px 14px; }
.error-box strong { display: block; }

/* Cases list */
.case-link { font-weight: 600; text-decoration: none; }
.case-link:hover { text-decoration: underline; }

/* How it works */
.hiw { display: grid; grid-template-columns: 240px 1fr; gap: 32px; align-items: start; }
.toc { position: sticky; top: 84px; max-height: calc(100vh - 100px); overflow: auto; }
.toc h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.toc ol { list-style: none; padding: 0; margin: 0; border-left: 2px solid var(--line); }
.toc a { display: block; padding: 5px 12px; margin-left: -2px; border-left: 2px solid transparent; text-decoration: none; color: var(--ink-2); font-size: 0.88rem; }
.toc a:hover { color: var(--accent); }
.toc a.active { border-left-color: var(--accent); color: var(--accent); font-weight: 600; }
.hiw-intro { font-size: 1.1rem; color: var(--ink-2); max-width: 70ch; }
.hiw-section { margin-top: 36px; scroll-margin-top: 80px; }
.hiw-section .summary-line { font-size: 1.02rem; color: var(--ink-2); font-weight: 500; }
.hiw-section p { max-width: 74ch; }
.figure { margin: 16px 0; }
.figure a { display: block; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); }
.figure img { display: block; max-width: 100%; height: auto; margin: 0 auto; }
.figure figcaption { color: var(--muted); font-size: 0.85rem; margin-top: 6px; }

@media (max-width: 900px) {
  .summary { grid-template-columns: 1fr; gap: 18px; }
  .hiw { grid-template-columns: 1fr; }
  .toc { position: static; max-height: none; }
  .cols-2 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .grid-2, .meters { grid-template-columns: 1fr; }
  .signals { grid-template-columns: 1fr; }
  .card { padding: 16px 14px; }
  .score-num { font-size: 3.2rem; }
  .main { padding-top: 16px; }
  .systems-panel { right: -8px; }
  .topbar-inner { gap: 6px 12px; }
  h1 { font-size: 1.35rem; }
}
@media print { .topbar, .footer { display: none; } }
EOF

input.content:
:root {
  --bg: #f4f6fa;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --ink: #0f1b33;
  --ink-2: #3d4a63;
  --muted: #566279;
  --line: #dbe1ea;
  --line-strong: #c3ccda;
  --navy: #14233f;
  --navy-ink: #ffffff;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --accent-soft: #e2f3f1;
  --focus: #1d4ed8;
  --shadow: 0 1px 2px rgba(15, 27, 51, 0.06), 0 2px 8px rgba(15, 27, 51, 0.05);

  --good-fg: #14633a;
  --good-bg: #e3f4ea;
  --good-bar: #2f9e66;
  --neutral-fg: #3d4a63;
  --neutral-bg: #e9edf3;
  --neutral-bar: #7b88a1;
  --caution-fg: #7a4a00;
  --caution-bg: #fdefd2;
  --caution-bar: #d9962b;
  --bad-fg: #9b1c1c;
  --bad-bg: #fde6e6;
  --bad-bar: #d04545;
  --info-fg: #1c4a99;
  --info-bg: #e4edfb;
  --info-bar: #4a7bd0;

  --radius: 10px;
  --radius-sm: 6px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0c1424;
    --surface: #131d33;
    --surface-2: #17233c;
    --ink: #e8edf6;
    --ink-2: #c0cadb;
    --muted: #9aa8c0;
    --line: #25334f;
    --line-strong: #34456a;
    --navy: #0a1120;
    --accent: #36b7ac;
    --accent-ink: #04201d;
    --accent-soft: #123a3a;
    --focus: #8fb4ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);

    --good-fg: #8fe0b2;
    --good-bg: #123a27;
    --good-bar: #3fb77a;
    --neutral-fg: #c0cadb;
    --neutral-bg: #1f2c47;
    --neutral-bar: #7b88a1;
    --caution-fg: #f4c677;
    --caution-bg: #3b2c0e;
    --caution-bar: #e0a23a;
    --bad-fg: #ffa5a5;
    --bad-bg: #431818;
    --bad-bar: #e06a6a;
    --info-fg: #a9c6ff;
    --info-bg: #172c52;
    --info-bar: #5f8fe0;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 76px; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { line-height: 1.25; margin: 0 0 0.5em; color: var(--ink); }
h1 { font-size: 1.6rem; letter-spacing: -0.01em; }
h2 { font-size: 1.25rem; }
h3 { font-size: 1.05rem; }
h4 { font-size: 0.95rem; }
p { margin: 0 0 0.8em; }
a { color: var(--accent); }
a:hover { text-decoration-thickness: 2px; }
code, .mono { font-family: var(--mono); font-size: 0.88em; }
ul, ol { margin: 0 0 0.8em; padding-left: 1.3em; }
li { margin-bottom: 0.25em; }
table { border-collapse: collapse; width: 100%; }

:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 3px; }

.skip-link {
  position: absolute; left: -999px; top: 0; background: var(--accent); color: var(--accent-ink);
  padding: 8px 14px; z-index: 100;
}
.skip-link:focus { left: 8px; top: 8px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* Layout */
.topbar { background: var(--navy); color: var(--navy-ink); position: sticky; top: 0; z-index: 30; }
.topbar-inner {
  max-width: 1160px; margin: 0 auto; padding: 10px 16px; display: flex; align-items: center;
  gap: 8px 24px; flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: inherit; }
.brand-mark { flex: none; }
.brand-name { font-weight: 700; font-size: 1.15rem; letter-spacing: 0.01em; display: block; line-height: 1.1; }
.brand-tag { font-size: 0.75rem; opacity: 0.8; display: block; }
.nav { display: flex; gap: 4px; flex-wrap: wrap; flex: 1; }
.nav a {
  color: #d6deee; text-decoration: none; padding: 7px 12px; border-radius: var(--radius-sm); font-weight: 500;
  font-size: 0.93rem;
}
.nav a:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.nav a.active { background: rgba(255, 255, 255, 0.16); color: #fff; }
.topbar :focus-visible { outline-color: #9ec1ff; }

.systems { position: relative; }
.systems-btn {
  display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.1); color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 999px; padding: 6px 12px; font: inherit;
  font-size: 0.85rem; cursor: pointer;
}
.systems-btn:hover { background: rgba(255, 255, 255, 0.18); }
.systems-panel {
  position: absolute; right: 0; top: calc(100% + 8px); width: min(360px, calc(100vw - 32px));
  background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25); padding: 14px; z-index: 40;
}
.systems-panel h2 { font-size: 0.95rem; margin-bottom: 8px; }
.system-row { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-top: 1px solid var(--line); }
.system-row:first-of-type { border-top: 0; }
.system-label { font-weight: 600; font-size: 0.9rem; }
.system-detail { font-size: 0.82rem; color: var(--muted); }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; flex: none; margin-top: 6px; }
.dot.on { background: #3fcf8e; }
.dot.off { background: transparent; border: 2px solid #f0a0a0; }
.systems-btn .dot { margin-top: 0; }
.dots { display: inline-flex; gap: 4px; }

.main { max-width: 1160px; margin: 0 auto; padding: 24px 16px 64px; }
.page-head { margin-bottom: 20px; }
.page-head p { color: var(--muted); max-width: 70ch; margin-bottom: 0; }
.footer { text-align: center; color: var(--muted); font-size: 0.82rem; padding: 0 16px 32px; }

/* Cards, buttons */
.card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px; box-shadow: var(--shadow);
}
.card + .card, .stack > * + * { margin-top: 16px; }
.card h2 { margin-bottom: 0.4em; }
.section { margin-top: 28px; }
.section-head { margin-bottom: 12px; }
.section-head h2 { margin-bottom: 2px; }
.section-head p { color: var(--muted); margin: 0; font-size: 0.92rem; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 9px 16px;
  border-radius: var(--radius-sm); border: 1px solid var(--line-strong); background: var(--surface);
  color: var(--ink); font: inherit; font-weight: 600; font-size: 0.92rem; cursor: pointer; text-decoration: none;
  min-height: 40px;
}
.btn:hover:not(:disabled) { background: var(--surface-2); border-color: var(--muted); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn.primary:hover:not(:disabled) { filter: brightness(0.93); background: var(--accent); }
.btn.small { padding: 5px 10px; min-height: 32px; font-size: 0.84rem; }
.btn-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.link-btn {
  background: none; border: 0; padding: 0; color: var(--accent); font: inherit; cursor: pointer;
  text-decoration: underline;
}

/* Pills, badges */
.pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.8rem;
  font-weight: 600; white-space: nowrap; background: var(--tone-bg); color: var(--tone-fg);
  border: 1px solid transparent;
}
.pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--tone-bar); }
.pill.plain::before { display: none; }
.badge {
  display: inline-block; padding: 2px 9px; border-radius: var(--radius-sm); font-size: 0.78rem; font-weight: 700;
  background: var(--tone-bg); color: var(--tone-fg); letter-spacing: 0.02em;
}
.tone-good { --tone-fg: var(--good-fg); --tone-bg: var(--good-bg); --tone-bar: var(--good-bar); }
.tone-neutral { --tone-fg: var(--neutral-fg); --tone-bg: var(--neutral-bg); --tone-bar: var(--neutral-bar); }
.tone-caution { --tone-fg: var(--caution-fg); --tone-bg: var(--caution-bg); --tone-bar: var(--caution-bar); }
.tone-bad { --tone-fg: var(--bad-fg); --tone-bg: var(--bad-bg); --tone-bar: var(--bad-bar); }
.tone-info { --tone-fg: var(--info-fg); --tone-bg: var(--info-bg); --tone-bar: var(--info-bar); }

.mode-synthetic { background: var(--caution-bg); color: var(--caution-fg); border: 1px solid var(--caution-bar); }
.mode-live { background: var(--info-bg); color: var(--info-fg); border: 1px solid var(--info-bar); }

.banner {
  display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius);
  background: var(--tone-bg); color: var(--tone-fg); border: 1px solid var(--tone-bar); margin-bottom: 14px;
}
.banner svg { flex: none; margin-top: 2px; }
.banner strong { display: block; }
.banner p { margin: 0; }
.banner-demo { font-weight: 700; font-size: 1rem; }

/* Forms */
.field { margin-bottom: 18px; }
.field label, .field .label, legend.label { display: block; font-weight: 600; margin-bottom: 4px; font-size: 0.93rem; }
.help { color: var(--muted); font-size: 0.84rem; margin: 4px 0 0; }
.input, .textarea, .select {
  width: 100%; font: inherit; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm); padding: 9px 11px; min-height: 40px;
}
.textarea { min-height: 96px; resize: vertical; }
.input[aria-invalid="true"], .textarea[aria-invalid="true"], .select[aria-invalid="true"] { border-color: var(--bad-bar); }
.input:disabled { background: var(--surface-2); }
.error-text { color: var(--bad-fg); font-size: 0.86rem; margin: 4px 0 0; font-weight: 500; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
.check { display: flex; gap: 10px; align-items: flex-start; }
.check input { width: 20px; height: 20px; margin-top: 2px; flex: none; accent-color: var(--accent); }

.choice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; }
.choice {
  display: block; position: relative; border: 2px solid var(--line); border-radius: var(--radius); padding: 14px 16px;
  background: var(--surface); cursor: pointer;
}
.choice:hover { border-color: var(--line-strong); }
.choice.selected { border-color: var(--accent); background: var(--accent-soft); }
.choice.disabled { opacity: 0.7; cursor: not-allowed; background: var(--surface-2); }
.choice input { position: absolute; opacity: 0; inset: 0; width: 100%; height: 100%; cursor: inherit; margin: 0; }
.choice:has(input:focus-visible) { outline: 3px solid var(--focus); outline-offset: 2px; }
.choice-title { font-weight: 700; display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.choice-body { color: var(--ink-2); font-size: 0.9rem; margin: 6px 0 0; }
.choice-check { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--line-strong); flex: none; }
.choice.selected .choice-check { border-color: var(--accent); background: var(--accent); box-shadow: inset 0 0 0 3px var(--accent-soft); }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.chip {
  display: inline-flex; align-items: center; gap: 4px; background: var(--neutral-bg); color: var(--ink);
  border-radius: 999px; padding: 3px 4px 3px 11px; font-size: 0.86rem;
}
.chip button {
  border: 0; background: transparent; cursor: pointer; width: 22px; height: 22px; border-radius: 50%; color: inherit;
  display: inline-flex; align-items: center; justify-content: center;
}
.chip button:hover { background: rgba(0, 0, 0, 0.12); }

/* Tables */
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.table-wrap table { min-width: 560px; }
th, td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: top; font-size: 0.9rem; }
th { background: var(--surface-2); font-weight: 600; color: var(--ink-2); font-size: 0.82rem; white-space: nowrap; }
tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
.pos { color: var(--good-fg); }
.neg { color: var(--bad-fg); }
.flag-list { list-style: none; padding: 0; margin: 4px 0 0; }
.flag-list li { color: var(--caution-fg); background: var(--caution-bg); border-radius: 4px; padding: 2px 8px; font-size: 0.8rem; margin-bottom: 3px; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 2px solid var(--line); margin-bottom: 14px; flex-wrap: wrap; }
.tab {
  background: none; border: 0; border-bottom: 3px solid transparent; margin-bottom: -2px; padding: 9px 14px;
  font: inherit; font-weight: 600; color: var(--muted); cursor: pointer;
}
.tab:hover { color: var(--ink); }
.tab[aria-selected="true"] { color: var(--accent); border-bottom-color: var(--accent); }
.tab .count { font-weight: 500; opacity: 0.8; margin-left: 4px; }

/* Disclosure */
details.disclosure { border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); margin-top: 10px; }
details.disclosure > summary {
  cursor: pointer; padding: 8px 12px; font-weight: 600; font-size: 0.88rem; color: var(--ink-2); list-style: none;
  display: flex; align-items: center; gap: 8px;
}
details.disclosure > summary::-webkit-details-marker { display: none; }
details.disclosure > summary::before {
  content: ""; width: 7px; height: 7px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
  transform: rotate(-45deg); transition: transform 0.15s; flex: none;
}
details.disclosure[open] > summary::before { transform: rotate(45deg); }
details.disclosure > .disc-body { padding: 4px 14px 12px; }

/* Case header */
.case-head h1 { margin-bottom: 4px; word-break: break-word; }
.case-meta { display: flex; gap: 8px 12px; flex-wrap: wrap; align-items: center; margin: 8px 0; }
.peer-list { color: var(--ink-2); margin: 4px 0; }
.thesis { background: var(--surface-2); border-left: 3px solid var(--accent); padding: 10px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; white-space: pre-wrap; margin: 0; }

/* Summary */
.summary { display: grid; grid-template-columns: minmax(200px, 260px) 1fr; gap: 28px; align-items: start; }
.score-box { text-align: center; padding: 18px 12px; border-radius: var(--radius); background: var(--tone-bg); color: var(--tone-fg); }
.score-num { font-size: 4rem; font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.score-num small { font-size: 1.1rem; font-weight: 600; opacity: 0.75; }
.score-none { font-size: 1.3rem; font-weight: 700; line-height: 1.25; padding: 10px 0; }
.score-band { font-size: 1.15rem; font-weight: 700; margin-top: 6px; }
.score-cap { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; margin-bottom: 6px; opacity: 0.85; }
.headline { font-size: 1.2rem; font-weight: 600; line-height: 1.4; margin-bottom: 16px; }
.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.meter-head { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; margin-bottom: 4px; }
.meter-name { font-weight: 700; font-size: 0.9rem; }
.meter-val { font-weight: 700; font-variant-numeric: tabular-nums; }
.meter-track { height: 12px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; position: relative; }
.meter-fill { height: 100%; border-radius: 999px; background: var(--tone-bar); }
.meter-sub { font-size: 0.84rem; color: var(--muted); margin-top: 3px; }
.infobox { background: var(--info-bg); color: var(--ink); border: 1px solid var(--info-bar); border-radius: var(--radius-sm); padding: 10px 14px; margin-top: 16px; font-size: 0.9rem; }
.infobox strong { color: var(--info-fg); display: block; margin-bottom: 2px; }
.infobox p { margin: 0; }

/* Signals */
.signals { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; }
.signal { display: flex; flex-direction: column; margin: 0 !important; }
.signal-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
.signal-name { font-size: 1.02rem; margin: 0; }
.signal-q { color: var(--muted); font-size: 0.88rem; margin: 2px 0 10px; font-style: italic; }
.bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
.bar-track { flex: 1; height: 10px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; }
.bar-fill { height: 100%; background: var(--tone-bar); border-radius: 999px; }
.bar-val { font-weight: 700; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; font-size: 0.9rem; }
.kv { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 0.84rem; margin-bottom: 8px; }
.signal .finding-text-plain { margin-bottom: 8px; }
.signal h4 { margin: 10px 0 2px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.signal ul.lim { color: var(--ink-2); font-size: 0.88rem; margin: 2px 0 0; }
.tech-list { font-family: var(--mono); font-size: 0.8rem; word-break: break-word; }

/* Findings */
.finding-group + .finding-group { margin-top: 20px; }
.finding-group > h3 { display: flex; gap: 8px; align-items: baseline; }
.finding-group > h3 .muted { font-weight: 400; font-size: 0.85rem; }
.finding { margin-top: 10px !important; border-left: 4px solid var(--tone-bar); padding: 14px 16px; }
.finding-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 6px; }
.finding-text { font-weight: 600; margin: 0 0 8px; font-size: 1rem; }
.finding h4 { margin: 10px 0 2px; font-size: 0.85rem; color: var(--ink-2); }
.finding ul { margin: 2px 0 0; font-size: 0.9rem; color: var(--ink-2); }
.ev-list { list-style: none; padding: 0 !important; }
.ev-item { padding: 6px 10px; background: var(--surface-2); border-radius: var(--radius-sm); margin-bottom: 4px; border-left: 3px solid var(--good-bar); }
.ev-item.counter { border-left-color: var(--bad-bar); background: var(--bad-bg); }
.ev-label { font-weight: 600; font-size: 0.88rem; color: var(--ink); }
.ev-meta { color: var(--muted); font-size: 0.8rem; }
.ev-item.counter .ev-meta { color: var(--bad-fg); }

/* Questions */
.question-list { padding-left: 0; list-style: none; counter-reset: q; }
.question-list li { counter-increment: q; display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); margin: 0; }
.question-list li:last-child { border-bottom: 0; }
.question-list li::before {
  content: counter(q); flex: none; width: 26px; height: 26px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
  font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-size: 0.85rem;
}

/* Timeline */
.timeline { list-style: none; padding: 0; margin: 0; position: relative; }
.timeline li { position: relative; padding: 0 0 18px 30px; margin: 0; }
.timeline li::before { content: ""; position: absolute; left: 9px; top: 18px; bottom: -2px; width: 2px; background: var(--line); }
.timeline li:last-child::before { display: none; }
.tl-dot { position: absolute; left: 2px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--tone-bar); border: 3px solid var(--surface); box-shadow: 0 0 0 1px var(--tone-bar); }
.tl-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.tl-title { font-weight: 600; }
.tl-detail { color: var(--ink-2); margin: 2px 0 0; font-size: 0.9rem; }
.tl-meta { color: var(--muted); font-size: 0.8rem; display: flex; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
.actor { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 1px 8px; border-radius: 4px; background: var(--tone-bg); color: var(--tone-fg); }

/* Progress */
.progress-panel { border-left: 5px solid var(--accent); }
.progress-q { font-size: 1.05rem; font-weight: 600; margin: 6px 0 12px; }
.spinner {
  width: 18px; height: 18px; border-radius: 50%; border: 3px solid var(--line-strong); border-top-color: var(--accent);
  animation: spin 0.9s linear infinite; display: inline-block; flex: none;
}
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 3s; } html { scroll-behavior: auto; } }
.progress-head { display: flex; align-items: center; gap: 10px; font-weight: 700; }
.live-steps { max-height: 320px; overflow: auto; margin-top: 8px; padding-top: 4px; }

/* Cost */
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
.stat { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 12px; }
.stat-v { font-size: 1.4rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
.stat-k { color: var(--muted); font-size: 0.82rem; }
.cols-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.cols-2 > .card { margin: 0 !important; }
.trace-row { display: flex; gap: 8px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
.trace-id { font-family: var(--mono); font-size: 0.82rem; background: var(--surface-2); border: 1px solid var(--line); padding: 3px 8px; border-radius: 4px; word-break: break-all; }

/* States */
.state { text-align: center; padding: 36px 16px; color: var(--muted); }
.state .spinner { margin-bottom: 8px; }
.error-box { background: var(--bad-bg); color: var(--bad-fg); border: 1px solid var(--bad-bar); border-radius: var(--radius); padding: 12px 14px; }
.error-box strong { display: block; }
.empty-box { padding: 18px; text-align: center; color: var(--muted); border: 1px dashed var(--line-strong); border-radius: var(--radius); background: var(--surface); }

/* Cases list */
.case-link { font-weight: 600; text-decoration: none; }
.case-link:hover { text-decoration: underline; }

/* How it works */
.hiw { display: grid; grid-template-columns: 240px 1fr; gap: 32px; align-items: start; }
.toc { position: sticky; top: 84px; max-height: calc(100vh - 100px); overflow: auto; }
.toc h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.toc ol { list-style: none; padding: 0; margin: 0; border-left: 2px solid var(--line); }
.toc a { display: block; padding: 5px 12px; margin-left: -2px; border-left: 2px solid transparent; text-decoration: none; color: var(--ink-2); font-size: 0.88rem; }
.toc a:hover { color: var(--accent); }
.toc a.active { border-left-color: var(--accent); color: var(--accent); font-weight: 600; }
.hiw-intro { font-size: 1.1rem; color: var(--ink-2); max-width: 70ch; }
.hiw-section { margin-top: 36px; scroll-margin-top: 80px; }
.hiw-section:first-of-type { margin-top: 20px; }
.hiw-section .summary-line { font-size: 1.02rem; color: var(--ink-2); font-weight: 500; }
.hiw-section p { max-width: 74ch; }
.figure { margin: 16px 0; }
.figure a { display: block; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); }
.figure img { display: block; max-width: 100%; height: auto; margin: 0 auto; }
.figure figcaption { color: var(--muted); font-size: 0.85rem; margin-top: 6px; }

@media (max-width: 900px) {
  .summary { grid-template-columns: 1fr; gap: 18px; }
  .hiw { grid-template-columns: 1fr; }
  .toc { position: static; max-height: none; }
  .cols-2 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .grid-2, .meters { grid-template-columns: 1fr; }
  .signals { grid-template-columns: 1fr; }
  .card { padding: 16px 14px; }
  .score-num { font-size: 3.2rem; }
  .main { padding-top: 16px; }
  .systems-panel { right: -8px; }
  .topbar-inner { gap: 6px 12px; }
  h1 { font-size: 1.35rem; }
}
@media print { .topbar, .footer { display: none; } }

toolu_01TzzY6iFRxXyAeiYZ5VTqNZ.content:
:root {
  --bg: #f4f6fa;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --ink: #0f1b33;
  --ink-2: #3d4a63;
  --muted: #566279;
  --line: #dbe1ea;
  --line-strong: #c3ccda;
  --navy: #14233f;
  --navy-ink: #ffffff;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --accent-soft: #e2f3f1;
  --focus: #1d4ed8;
  --shadow: 0 1px 2px rgba(15, 27, 51, 0.06), 0 2px 8px rgba(15, 27, 51, 0.05);

  --good-fg: #14633a;
  --good-bg: #e3f4ea;
  --good-bar: #2f9e66;
  --neutral-fg: #3d4a63;
  --neutral-bg: #e9edf3;
  --neutral-bar: #7b88a1;
  --caution-fg: #7a4a00;
  --caution-bg: #fdefd2;
  --caution-bar: #d9962b;
  --bad-fg: #9b1c1c;
  --bad-bg: #fde6e6;
  --bad-bar: #d04545;
  --info-fg: #1c4a99;
  --info-bg: #e4edfb;
  --info-bar: #4a7bd0;

  --radius: 10px;
  --radius-sm: 6px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0c1424;
    --surface: #131d33;
    --surface-2: #17233c;
    --ink: #e8edf6;
    --ink-2: #c0cadb;
    --muted: #9aa8c0;
    --line: #25334f;
    --line-strong: #34456a;
    --navy: #0a1120;
    --accent: #36b7ac;
    --accent-ink: #04201d;
    --accent-soft: #123a3a;
    --focus: #8fb4ff;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);

    --good-fg: #8fe0b2;
    --good-bg: #123a27;
    --good-bar: #3fb77a;
    --neutral-fg: #c0cadb;
    --neutral-bg: #1f2c47;
    --neutral-bar: #7b88a1;
    --caution-fg: #f4c677;
    --caution-bg: #3b2c0e;
    --caution-bar: #e0a23a;
    --bad-fg: #ffa5a5;
    --bad-bg: #431818;
    --bad-bar: #e06a6a;
    --info-fg: #a9c6ff;
    --info-bg: #172c52;
    --info-bar: #5f8fe0;
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 76px; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { line-height: 1.25; margin: 0 0 0.5em; color: var(--ink); }
h1 { font-size: 1.6rem; letter-spacing: -0.01em; }
h2 { font-size: 1.25rem; }
h3 { font-size: 1.05rem; }
h4 { font-size: 0.95rem; }
p { margin: 0 0 0.8em; }
a { color: var(--accent); }
a:hover { text-decoration-thickness: 2px; }
code, .mono { font-family: var(--mono); font-size: 0.88em; }
ul, ol { margin: 0 0 0.8em; padding-left: 1.3em; }
li { margin-bottom: 0.25em; }
table { border-collapse: collapse; width: 100%; }

:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 3px; }

.skip-link {
  position: absolute; left: -999px; top: 0; background: var(--accent); color: var(--accent-ink);
  padding: 8px 14px; z-index: 100;
}
.skip-link:focus { left: 8px; top: 8px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* Layout */
.topbar { background: var(--navy); color: var(--navy-ink); position: sticky; top: 0; z-index: 30; }
.topbar-inner {
  max-width: 1160px; margin: 0 auto; padding: 10px 16px; display: flex; align-items: center;
  gap: 8px 24px; flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: inherit; }
.brand-mark { flex: none; }
.brand-name { font-weight: 700; font-size: 1.15rem; letter-spacing: 0.01em; display: block; line-height: 1.1; }
.brand-tag { font-size: 0.75rem; opacity: 0.8; display: block; }
.nav { display: flex; gap: 4px; flex-wrap: wrap; flex: 1; }
.nav a {
  color: #d6deee; text-decoration: none; padding: 7px 12px; border-radius: var(--radius-sm); font-weight: 500;
  font-size: 0.93rem;
}
.nav a:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.nav a.active { background: rgba(255, 255, 255, 0.16); color: #fff; }
.topbar :focus-visible { outline-color: #9ec1ff; }

.systems { position: relative; }
.systems-btn {
  display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.1); color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.25); border-radius: 999px; padding: 6px 12px; font: inherit;
  font-size: 0.85rem; cursor: pointer;
}
.systems-btn:hover { background: rgba(255, 255, 255, 0.18); }
.systems-panel {
  position: absolute; right: 0; top: calc(100% + 8px); width: min(360px, calc(100vw - 32px));
  background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25); padding: 14px; z-index: 40;
}
.systems-panel h2 { font-size: 0.95rem; margin-bottom: 8px; }
.system-row { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-top: 1px solid var(--line); }
.system-row:first-of-type { border-top: 0; }
.system-label { font-weight: 600; font-size: 0.9rem; }
.system-detail { font-size: 0.82rem; color: var(--muted); }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; flex: none; margin-top: 6px; }
.dot.on { background: #3fcf8e; }
.dot.off { background: transparent; border: 2px solid #f0a0a0; }
.systems-btn .dot { margin-top: 0; }
.dots { display: inline-flex; gap: 4px; }

.main { max-width: 1160px; margin: 0 auto; padding: 24px 16px 64px; }
.page-head { margin-bottom: 20px; }
.page-head p { color: var(--muted); max-width: 70ch; margin-bottom: 0; }
.footer { text-align: center; color: var(--muted); font-size: 0.82rem; padding: 0 16px 32px; }

/* Cards, buttons */
.card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px; box-shadow: var(--shadow);
}
.card + .card, .stack > * + * { margin-top: 16px; }
.card h2 { margin-bottom: 0.4em; }
.section { margin-top: 28px; }
.section-head { margin-bottom: 12px; }
.section-head h2 { margin-bottom: 2px; }
.section-head p { color: var(--muted); margin: 0; font-size: 0.92rem; }
.muted { color: var(--muted); }
.small { font-size: 0.85rem; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 9px 16px;
  border-radius: var(--radius-sm); border: 1px solid var(--line-strong); background: var(--surface);
  color: var(--ink); font: inherit; font-weight: 600; font-size: 0.92rem; cursor: pointer; text-decoration: none;
  min-height: 40px;
}
.btn:hover:not(:disabled) { background: var(--surface-2); border-color: var(--muted); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn.primary:hover:not(:disabled) { filter: brightness(0.93); background: var(--accent); }
.btn.small { padding: 5px 10px; min-height: 32px; font-size: 0.84rem; }
.btn-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.link-btn {
  background: none; border: 0; padding: 0; color: var(--accent); font: inherit; cursor: pointer;
  text-decoration: underline;
}

/* Pills, badges */
.pill {
  display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.8rem;
  font-weight: 600; white-space: nowrap; background: var(--tone-bg); color: var(--tone-fg);
  border: 1px solid transparent;
}
.pill::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--tone-bar); }
.pill.plain::before { display: none; }
.badge {
  display: inline-block; padding: 2px 9px; border-radius: var(--radius-sm); font-size: 0.78rem; font-weight: 700;
  background: var(--tone-bg); color: var(--tone-fg); letter-spacing: 0.02em;
}
.tone-good { --tone-fg: var(--good-fg); --tone-bg: var(--good-bg); --tone-bar: var(--good-bar); }
.tone-neutral { --tone-fg: var(--neutral-fg); --tone-bg: var(--neutral-bg); --tone-bar: var(--neutral-bar); }
.tone-caution { --tone-fg: var(--caution-fg); --tone-bg: var(--caution-bg); --tone-bar: var(--caution-bar); }
.tone-bad { --tone-fg: var(--bad-fg); --tone-bg: var(--bad-bg); --tone-bar: var(--bad-bar); }
.tone-info { --tone-fg: var(--info-fg); --tone-bg: var(--info-bg); --tone-bar: var(--info-bar); }

.mode-synthetic { background: var(--caution-bg); color: var(--caution-fg); border: 1px solid var(--caution-bar); }
.mode-live { background: var(--info-bg); color: var(--info-fg); border: 1px solid var(--info-bar); }

.banner {
  display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radius);
  background: var(--tone-bg); color: var(--tone-fg); border: 1px solid var(--tone-bar); margin-bottom: 14px;
}
.banner svg { flex: none; margin-top: 2px; }
.banner strong { display: block; }
.banner p { margin: 0; }
.banner-demo { font-weight: 700; font-size: 1rem; }

/* Forms */
.field { margin-bottom: 18px; }
.field label, .field .label, legend.label { display: block; font-weight: 600; margin-bottom: 4px; font-size: 0.93rem; }
.help { color: var(--muted); font-size: 0.84rem; margin: 4px 0 0; }
.input, .textarea, .select {
  width: 100%; font: inherit; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm); padding: 9px 11px; min-height: 40px;
}
.textarea { min-height: 96px; resize: vertical; }
.input[aria-invalid="true"], .textarea[aria-invalid="true"], .select[aria-invalid="true"] { border-color: var(--bad-bar); }
.input:disabled { background: var(--surface-2); }
.error-text { color: var(--bad-fg); font-size: 0.86rem; margin: 4px 0 0; font-weight: 500; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
.check { display: flex; gap: 10px; align-items: flex-start; }
.check input { width: 20px; height: 20px; margin-top: 2px; flex: none; accent-color: var(--accent); }

.choice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; }
.choice {
  display: block; position: relative; border: 2px solid var(--line); border-radius: var(--radius); padding: 14px 16px;
  background: var(--surface); cursor: pointer;
}
.choice:hover { border-color: var(--line-strong); }
.choice.selected { border-color: var(--accent); background: var(--accent-soft); }
.choice.disabled { opacity: 0.7; cursor: not-allowed; background: var(--surface-2); }
.choice input { position: absolute; opacity: 0; inset: 0; width: 100%; height: 100%; cursor: inherit; margin: 0; }
.choice:has(input:focus-visible) { outline: 3px solid var(--focus); outline-offset: 2px; }
.choice-title { font-weight: 700; display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.choice-body { color: var(--ink-2); font-size: 0.9rem; margin: 6px 0 0; }
.choice-check { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--line-strong); flex: none; }
.choice.selected .choice-check { border-color: var(--accent); background: var(--accent); box-shadow: inset 0 0 0 3px var(--accent-soft); }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.chip {
  display: inline-flex; align-items: center; gap: 4px; background: var(--neutral-bg); color: var(--ink);
  border-radius: 999px; padding: 3px 4px 3px 11px; font-size: 0.86rem;
}
.chip button {
  border: 0; background: transparent; cursor: pointer; width: 22px; height: 22px; border-radius: 50%; color: inherit;
  display: inline-flex; align-items: center; justify-content: center;
}
.chip button:hover { background: rgba(0, 0, 0, 0.12); }

/* Tables */
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
.table-wrap table { min-width: 560px; }
th, td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--line); vertical-align: top; font-size: 0.9rem; }
th { background: var(--surface-2); font-weight: 600; color: var(--ink-2); font-size: 0.82rem; white-space: nowrap; }
tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
.pos { color: var(--good-fg); }
.neg { color: var(--bad-fg); }
.flag-list { list-style: none; padding: 0; margin: 4px 0 0; }
.flag-list li { color: var(--caution-fg); background: var(--caution-bg); border-radius: 4px; padding: 2px 8px; font-size: 0.8rem; margin-bottom: 3px; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 2px solid var(--line); margin-bottom: 14px; flex-wrap: wrap; }
.tab {
  background: none; border: 0; border-bottom: 3px solid transparent; margin-bottom: -2px; padding: 9px 14px;
  font: inherit; font-weight: 600; color: var(--muted); cursor: pointer;
}
.tab:hover { color: var(--ink); }
.tab[aria-selected="true"] { color: var(--accent); border-bottom-color: var(--accent); }
.tab .count { font-weight: 500; opacity: 0.8; margin-left: 4px; }

/* Disclosure */
details.disclosure { border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); margin-top: 10px; }
details.disclosure > summary {
  cursor: pointer; padding: 8px 12px; font-weight: 600; font-size: 0.88rem; color: var(--ink-2); list-style: none;
  display: flex; align-items: center; gap: 8px;
}
details.disclosure > summary::-webkit-details-marker { display: none; }
details.disclosure > summary::before {
  content: ""; width: 7px; height: 7px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
  transform: rotate(-45deg); transition: transform 0.15s; flex: none;
}
details.disclosure[open] > summary::before { transform: rotate(45deg); }
details.disclosure > .disc-body { padding: 4px 14px 12px; }

/* Case header */
.case-head h1 { margin-bottom: 4px; word-break: break-word; }
.case-meta { display: flex; gap: 8px 12px; flex-wrap: wrap; align-items: center; margin: 8px 0; }
.peer-list { color: var(--ink-2); margin: 4px 0; }
.thesis { background: var(--surface-2); border-left: 3px solid var(--accent); padding: 10px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; white-space: pre-wrap; margin: 0; }

/* Summary */
.summary { display: grid; grid-template-columns: minmax(200px, 260px) 1fr; gap: 28px; align-items: start; }
.score-box { text-align: center; padding: 18px 12px; border-radius: var(--radius); background: var(--tone-bg); color: var(--tone-fg); }
.score-num { font-size: 4rem; font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.score-num small { font-size: 1.1rem; font-weight: 600; opacity: 0.75; }
.score-none { font-size: 1.3rem; font-weight: 700; line-height: 1.25; padding: 10px 0; }
.score-band { font-size: 1.15rem; font-weight: 700; margin-top: 6px; }
.score-cap { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; margin-bottom: 6px; opacity: 0.85; }
.headline { font-size: 1.2rem; font-weight: 600; line-height: 1.4; margin-bottom: 16px; }
.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.meter-head { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; margin-bottom: 4px; }
.meter-name { font-weight: 700; font-size: 0.9rem; }
.meter-val { font-weight: 700; font-variant-numeric: tabular-nums; }
.meter-track { height: 12px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; position: relative; }
.meter-fill { height: 100%; border-radius: 999px; background: var(--tone-bar); }
.meter-sub { font-size: 0.84rem; color: var(--muted); margin-top: 3px; }
.infobox { background: var(--info-bg); color: var(--ink); border: 1px solid var(--info-bar); border-radius: var(--radius-sm); padding: 10px 14px; margin-top: 16px; font-size: 0.9rem; }
.infobox strong { color: var(--info-fg); display: block; margin-bottom: 2px; }
.infobox p { margin: 0; }

/* Signals */
.signals { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 16px; }
.signal { display: flex; flex-direction: column; margin: 0 !important; }
.signal-head { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; }
.signal-name { font-size: 1.02rem; margin: 0; }
.signal-q { color: var(--muted); font-size: 0.88rem; margin: 2px 0 10px; font-style: italic; }
.bar-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
.bar-track { flex: 1; height: 10px; border-radius: 999px; background: var(--neutral-bg); overflow: hidden; }
.bar-fill { height: 100%; background: var(--tone-bar); border-radius: 999px; }
.bar-val { font-weight: 700; min-width: 4.5em; text-align: right; font-variant-numeric: tabular-nums; font-size: 0.9rem; }
.kv { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 0.84rem; margin-bottom: 8px; }
.signal .finding-text-plain { margin-bottom: 8px; }
.signal h4 { margin: 10px 0 2px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.signal ul.lim { color: var(--ink-2); font-size: 0.88rem; margin: 2px 0 0; }
.tech-list { font-family: var(--mono); font-size: 0.8rem; word-break: break-word; }

/* Findings */
.finding-group + .finding-group { margin-top: 20px; }
.finding-group > h3 { display: flex; gap: 8px; align-items: baseline; }
.finding-group > h3 .muted { font-weight: 400; font-size: 0.85rem; }
.finding { margin-top: 10px !important; border-left: 4px solid var(--tone-bar); padding: 14px 16px; }
.finding-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 6px; }
.finding-text { font-weight: 600; margin: 0 0 8px; font-size: 1rem; }
.finding h4 { margin: 10px 0 2px; font-size: 0.85rem; color: var(--ink-2); }
.finding ul { margin: 2px 0 0; font-size: 0.9rem; color: var(--ink-2); }
.ev-list { list-style: none; padding: 0 !important; }
.ev-item { padding: 6px 10px; background: var(--surface-2); border-radius: var(--radius-sm); margin-bottom: 4px; border-left: 3px solid var(--good-bar); }
.ev-item.counter { border-left-color: var(--bad-bar); background: var(--bad-bg); }
.ev-label { font-weight: 600; font-size: 0.88rem; color: var(--ink); }
.ev-meta { color: var(--muted); font-size: 0.8rem; }
.ev-item.counter .ev-meta { color: var(--bad-fg); }

/* Questions */
.question-list { padding-left: 0; list-style: none; counter-reset: q; }
.question-list li { counter-increment: q; display: flex; gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--line); margin: 0; }
.question-list li:last-child { border-bottom: 0; }
.question-list li::before {
  content: counter(q); flex: none; width: 26px; height: 26px; border-radius: 50%; background: var(--accent-soft); color: var(--accent);
  font-weight: 700; display: inline-flex; align-items: center; justify-content: center; font-size: 0.85rem;
}

/* Timeline */
.timeline { list-style: none; padding: 0; margin: 0; position: relative; }
.timeline li { position: relative; padding: 0 0 18px 30px; margin: 0; }
.timeline li::before { content: ""; position: absolute; left: 9px; top: 18px; bottom: -2px; width: 2px; background: var(--line); }
.timeline li:last-child::before { display: none; }
.tl-dot { position: absolute; left: 2px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--tone-bar); border: 3px solid var(--surface); box-shadow: 0 0 0 1px var(--tone-bar); }
.tl-top { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.tl-title { font-weight: 600; }
.tl-detail { color: var(--ink-2); margin: 2px 0 0; font-size: 0.9rem; }
.tl-meta { color: var(--muted); font-size: 0.8rem; display: flex; gap: 12px; flex-wrap: wrap; margin-top: 2px; }
.actor { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 1px 8px; border-radius: 4px; background: var(--tone-bg); color: var(--tone-fg); }

/* Progress */
.progress-panel { border-left: 5px solid var(--accent); }
.progress-q { font-size: 1.05rem; font-weight: 600; margin: 6px 0 12px; }
.spinner {
  width: 18px; height: 18px; border-radius: 50%; border: 3px solid var(--line-strong); border-top-color: var(--accent);
  animation: spin 0.9s linear infinite; display: inline-block; flex: none;
}
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation-duration: 3s; } html { scroll-behavior: auto; } }
.progress-head { display: flex; align-items: center; gap: 10px; font-weight: 700; }
.live-steps { max-height: 320px; overflow: auto; margin-top: 8px; padding-top: 4px; }

/* Cost */
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
.stat { background: var(--surface-2); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 12px; }
.stat-v { font-size: 1.4rem; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.2; }
.stat-k { color: var(--muted); font-size: 0.82rem; }
.cols-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.cols-2 > .card { margin: 0 !important; }
.trace-row { display: flex; gap: 8px; align-items: center; margin-bottom: 6px; flex-wrap: wrap; }
.trace-id { font-family: var(--mono); font-size: 0.82rem; background: var(--surface-2); border: 1px solid var(--line); padding: 3px 8px; border-radius: 4px; word-break: break-all; }

/* States */
.state { text-align: center; padding: 36px 16px; color: var(--muted); }
.state .spinner { margin-bottom: 8px; }
.error-box { background: var(--bad-bg); color: var(--bad-fg); border: 1px solid var(--bad-bar); border-radius: var(--radius); padding: 12px 14px; }
.error-box strong { display: block; }
.empty-box { padding: 18px; text-align: center; color: var(--muted); border: 1px dashed var(--line-strong); border-radius: var(--radius); background: var(--surface); }

/* Cases list */
.case-link { font-weight: 600; text-decoration: none; }
.case-link:hover { text-decoration: underline; }

/* How it works */
.hiw { display: grid; grid-template-columns: 240px 1fr; gap: 32px; align-items: start; }
.toc { position: sticky; top: 84px; max-height: calc(100vh - 100px); overflow: auto; }
.toc h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); }
.toc ol { list-style: none; padding: 0; margin: 0; border-left: 2px solid var(--line); }
.toc a { display: block; padding: 5px 12px; margin-left: -2px; border-left: 2px solid transparent; text-decoration: none; color: var(--ink-2); font-size: 0.88rem; }
.toc a:hover { color: var(--accent); }
.toc a.active { border-left-color: var(--accent); color: var(--accent); font-weight: 600; }
.hiw-intro { font-size: 1.1rem; color: var(--ink-2); max-width: 70ch; }
.hiw-section { margin-top: 36px; scroll-margin-top: 80px; }
.hiw-section:first-of-type { margin-top: 20px; }
.hiw-section .summary-line { font-size: 1.02rem; color: var(--ink-2); font-weight: 500; }
.hiw-section p { max-width: 74ch; }
.figure { margin: 16px 0; }
.figure a { display: block; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface); }
.figure img { display: block; max-width: 100%; height: auto; margin: 0 auto; }
.figure figcaption { color: var(--muted); font-size: 0.85rem; margin-top: 6px; }

@media (max-width: 900px) {
  .summary { grid-template-columns: 1fr; gap: 18px; }
  .hiw { grid-template-columns: 1fr; }
  .toc { position: static; max-height: none; }
  .cols-2 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .grid-2, .meters { grid-template-columns: 1fr; }
  .signals { grid-template-columns: 1fr; }
  .card { padding: 16px 14px; }
  .score-num { font-size: 3.2rem; }
  .main { padding-top: 16px; }
  .systems-panel { right: -8px; }
  .topbar-inner { gap: 6px 12px; }
  h1 { font-size: 1.35rem; }
}
@media print { .topbar, .footer { display: none; } }

