          const selected = s.id === selectedId;
          return (
            <label key={s.id} className={`choice${selected ? " selected" : ""}`}>
              <input
                type="radio"
                name="scenario"
                value={s.id}
                checked={selected}
                onChange={() => onSelect(s)}
              />
              <span className="choice-title">
                <span>{s.label}</span>
                <span className="choice-check" aria-hidden="true" />
              </span>
              <span className="choice-body" style={{ display: "block" }}>
                {s.description}
              </span>
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

