import { StatusPill } from "./ui";

const STATUS_LABEL: Record<IdentityResult["status"], string> = {
  ok: "Matched",
  ambiguous: "Ambiguous",
  mismatch: "Mismatch",
  no_match: "No match",
  error: "Check failed",
};

const STATUS_TONE: Record<IdentityResult["status"], Tone> = {
  ok: "good",
  ambiguous: "caution",
  mismatch: "bad",
  no_match: "bad",
  error: "bad",
};

interface Props {
  results: IdentityResult[];
